-- Wraps a collision grid with the map cell's global tile origin so the runtime
-- can address tiles in either local (0..width-1 within the cell) or
-- global (matrix-wide) coordinates. Blocking is exactly the asset's semantic
-- `blocked` cell flag; behavior and terrainResponseId are opaque cell fields
-- the runtime carries for HUD/diagnostics. Runtime maps hold the compact
-- CollisionGridAsset view over the resident generated bytes and read one cell
-- on demand; getLocal returns a copy so no consumer can mutate a shared cell.
-- The wrapper owns the source interest behind that view and returns it exactly
-- once on dispose. Authoring and fixture callers may keep passing a decoded
-- grid. Pure domain module (no love); the G4CL binary format lives in
-- CollisionGridAsset and the HGSS source packing lives in romdump.

local CollisionGrid = {}
CollisionGrid.__index = CollisionGrid

---@class CollisionGrid
---@field grid { width: integer, height: integer, cells: table[] }|CollisionGridAsset.View compact runtime view or an authoring decoded grid
---@field worldOriginX integer
---@field worldOriginZ integer
---@field width integer
---@field height integer
---@field localToGlobal fun(self: CollisionGrid, localX: number, localZ: number): number, number
---@field globalToLocal fun(self: CollisionGrid, globalX: number, globalZ: number): number, number
---@field getLocal fun(self: CollisionGrid, localX: integer, localZ: integer): table<string, unknown>
---@field containsLocal fun(self: CollisionGrid, localX: number, localZ: number): boolean
---@field isBlockedLocal fun(self: CollisionGrid, localX: number, localZ: number): boolean
---@field isBlockedGlobal fun(self: CollisionGrid, globalX: number, globalZ: number): boolean
---@field dispose fun(self: CollisionGrid)
---@field private _view CollisionGridAsset.View?
---@field private _sourceLease { value: unknown, release: fun(self: unknown) }?
---@field private _disposed boolean

local function finiteInteger(value)
  return type(value) == "number"
    and value == value
    and value ~= math.huge
    and value ~= -math.huge
    and value == math.floor(value)
end

---@param collisionGrid { width: integer, height: integer, cells: table[] }|CollisionGridAsset.View compact view or decoded grid
---@param opts { worldOriginX?: integer, worldOriginZ?: integer, sourceLease?: { value: unknown, release: fun(self: unknown) } }|nil
---@return CollisionGrid
function CollisionGrid.new(collisionGrid, opts)
  assert(
    collisionGrid
      and type(collisionGrid.width) == "number"
      and (type(collisionGrid.cells) == "table" or type(collisionGrid.cell) == "function"),
    "CollisionGrid.new requires a compact collision view or a decoded collision grid"
  )
  opts = opts or {}
  local compact = type(collisionGrid.cells) ~= "table"
  local sourceLease = opts.sourceLease
  if compact then
    assert(sourceLease ~= nil, "a compact collision view requires the source interest behind its bytes")
  else
    assert(sourceLease == nil, "a decoded collision grid borrows no resident source")
  end
  local instance = setmetatable({
    grid = collisionGrid,
    worldOriginX = opts.worldOriginX or 0,
    worldOriginZ = opts.worldOriginZ or 0,
    width = collisionGrid.width,
    height = collisionGrid.height,
    _view = compact and collisionGrid or nil,
    _sourceLease = sourceLease,
    _disposed = false,
  }, CollisionGrid)
  return instance --[[@as CollisionGrid]]
end

-- A disposed wrapper no longer owns the bytes behind its view.
function CollisionGrid:_assertLive()
  assert(not self._disposed, "collision grid is disposed")
end

function CollisionGrid:globalToLocal(globalX, globalZ)
  return globalX - self.worldOriginX, globalZ - self.worldOriginZ
end

function CollisionGrid:localToGlobal(localX, localZ)
  return localX + self.worldOriginX, localZ + self.worldOriginZ
end

-- Cell coordinates are finite integers: a fractional coordinate would
-- otherwise read the shifted neighbouring cell.
function CollisionGrid:containsLocal(localX, localZ)
  self:_assertLive()
  return finiteInteger(localX)
    and finiteInteger(localZ)
    and localX >= 0
    and localZ >= 0
    and localX < self.width
    and localZ < self.height
end

-- The full cell record (behavior/terrainResponseId/blocked) for a local tile,
-- copied so callers cannot mutate the shared backing. A compact view answers
-- one cell from the borrowed bytes; nothing per-tile is retained.
function CollisionGrid:getLocal(localX, localZ)
  assert(self:containsLocal(localX, localZ), "local tile outside collision grid")
  local index = localZ * self.width + localX
  local view = self._view
  if view ~= nil then
    return view:cell(index)
  end
  local cell = self.grid.cells[index + 1]
  return {
    behavior = cell.behavior,
    terrainResponseId = cell.terrainResponseId,
    blocked = cell.blocked,
  }
end

function CollisionGrid:isBlockedLocal(localX, localZ)
  assert(self:containsLocal(localX, localZ), "local tile outside collision grid")
  local index = localZ * self.width + localX
  local view = self._view
  if view ~= nil then
    return view:blocked(index)
  end
  return self.grid.cells[index + 1].blocked == true
end

function CollisionGrid:isBlockedGlobal(globalX, globalZ)
  local lx, lz = self:globalToLocal(globalX, globalZ)
  return self:isBlockedLocal(lx, lz)
end

-- Return the borrowed compact source interest exactly once and drop every
-- reference to the view. Idempotent: a second dispose touches nothing.
function CollisionGrid:dispose()
  if self._disposed then
    return
  end
  self._disposed = true
  self._view = nil
  self.grid = nil
  local sourceLease = self._sourceLease
  self._sourceLease = nil
  if sourceLease ~= nil then
    sourceLease:release()
  end
end

return CollisionGrid
